questionvariables.text:
stack_include("https://raw.githubusercontent.com/STACK-for-Chemistry/STACK-for-Chemistry/refs/heads/main/Modules/Utilized/reactions.mac");
stack_include("https://raw.githubusercontent.com/STACK-for-Chemistry/STACK-for-Chemistry/refs/heads/main/Modules/Utilized/thermodynamictables.mac");
stack_unit_si_declare(true);

/* The species-count filter selects reactions with exactly two species on each side. */
reaction_candidates: chem_reaction_filter_by_species(2, 2);

/* Keep only reactions for which every species has both required thermo values. */
thermo_complete(name) := block([reactants, products, items, item, h_value, s_value, valid],
  reactants: chem_reaction_reactants(name),
  products: chem_reaction_products(name),
  items: append(reactants, products),
  valid: true,
  for item in items do (
    h_value: chem_thermo_data(first(item), "DeltaHf", second(item)),
    s_value: chem_thermo_data(first(item), "S", second(item)),
    if is(h_value = false) or is(h_value = null) or is(s_value = false) or is(s_value = null) then valid: false
  ),
  valid
);
/* Usually the first random candidate has complete data. Avoid filtering every
   reaction (and repeatedly looking up every species) during question import. */
reaction_name: false;
attempt: 0;
while is(reaction_name = false) and attempt < 20 do (
  attempt: attempt + 1,
  candidate_name: rand(reaction_candidates),
  if thermo_complete(candidate_name) then reaction_name: candidate_name
);

/* Deterministic fallback guarantees a valid selection if random attempts miss. */
candidate_index: 1;
while is(reaction_name = false) and candidate_index <= length(reaction_candidates) do (
  candidate_name: reaction_candidates[candidate_index],
  if thermo_complete(candidate_name) then reaction_name: candidate_name,
  candidate_index: candidate_index + 1
);

reactants: chem_reaction_reactants(reaction_name);
products: chem_reaction_products(reaction_name);
reaction_equation: chem_reaction_equation(reaction_name);

temperature: rand([250, 275, 300, 325, 350, 375, 400, 425, 450, 475, 500]);

round_sig(x) := block([power], if is(x = 0) then 0 else (power: 2-floor(log(abs(x))/log(10)), float(round(x*10^power)/10^power)));

thermo_table_rows: "";
delta_h_raw: 0;
delta_s_raw: 0;
for item in reactants do (
  h_value: chem_thermo_data(first(item), "DeltaHf", second(item)),
  s_value: chem_thermo_data(first(item), "S", second(item)),
  delta_h_raw: delta_h_raw - third(item)*h_value,
  delta_s_raw: delta_s_raw - third(item)*s_value,
  species_display: sconcat("\\ce{", first(item), "(", second(item), ")}"),
  thermo_table_rows: sconcat(thermo_table_rows,
    "<tr><td style=\"border: 1px solid #999; padding: 0.45em 0.7em;\">\\(", string(third(item)), "\\,", species_display, "\\)</td>",
    "<td style=\"border: 1px solid #999; padding: 0.45em 0.7em; text-align: right;\">", string(h_value), "</td>",
    "<td style=\"border: 1px solid #999; padding: 0.45em 0.7em; text-align: right;\">", string(s_value), "</td></tr>")
);
for item in products do (
  h_value: chem_thermo_data(first(item), "DeltaHf", second(item)),
  s_value: chem_thermo_data(first(item), "S", second(item)),
  delta_h_raw: delta_h_raw + third(item)*h_value,
  delta_s_raw: delta_s_raw + third(item)*s_value,
  species_display: sconcat("\\ce{", first(item), "(", second(item), ")}"),
  thermo_table_rows: sconcat(thermo_table_rows,
    "<tr><td style=\"border: 1px solid #999; padding: 0.45em 0.7em;\">\\(", string(third(item)), "\\,", species_display, "\\)</td>",
    "<td style=\"border: 1px solid #999; padding: 0.45em 0.7em; text-align: right;\">", string(h_value), "</td>",
    "<td style=\"border: 1px solid #999; padding: 0.45em 0.7em; text-align: right;\">", string(s_value), "</td></tr>")
);
delta_g_raw: delta_h_raw - temperature*delta_s_raw/1000;
delta_h_answer_value: round_sig(delta_h_raw);
delta_s_answer_value: round_sig(delta_s_raw);
delta_g_answer_value: round_sig(delta_g_raw);
ta_delta_h: stackunits(delta_h_answer_value, kJ*mol^(-1));
ta_delta_s: stackunits(delta_s_answer_value, J*mol^(-1)*K^(-1));
ta_delta_g: stackunits(delta_g_answer_value, kJ*mol^(-1));
